import QRCode, { type QRCodeSegment } from "qrcode";
import {
  type BarcodeParts,
  buildScanUrlParts,
  rejectRemovedBarcodeFormat,
  type ScanUrlOptions,
  type VerifiablEnvironment,
} from "../payload.js";

/**
 * Branded "Secured by Verifiabl" barcode renderer.
 *
 * The QR matrix comes from the `qrcode` library. Data modules are rendered
 * as standard square modules, with rounded finder patterns in the three
 * large corner sections.
 */

export interface BarcodeSvgOptions {
  /** API environment for the public QR scan URL. Defaults to "production". */
  environment?: VerifiablEnvironment;
  /**
   * Advanced override for the public QR scan URL origin. Defaults to the
   * selected environment's scan URL origin. Must use https.
   */
  scanBaseUrl?: string;
  /**
   * Badge arrangement (default "vertical"). "vertical" puts the navy "Secured
   * by Verifiabl" header above the QR code. "horizontal" puts a light-tinted
   * "Secured by Verifiabl" frame to the right of the QR code, for short, wide
   * spaces.
   */
  layout?: BarcodeLayout;
  /**
   * Total badge width in SVG user units / px. The default is the minimum: 480
   * for the vertical layout and 940 for the horizontal layout. Both minimums
   * render the QR code at the same size.
   */
  width?: number;
  /**
   * Highest QR error-correction level to use. The renderer still steps below
   * this only when the payload would not otherwise fit the fixed frame.
   *
   * Default "M" (~15% damage recovery) keeps the modules large and the symbol
   * visually clean. Choose "Q" (~25% recovery) for documents expected to take
   * heavy print wear, accepting a denser code (one or two QR versions larger).
   */
  maxErrorCorrection?: "Q" | "M";
}

/** Badge arrangement: the header above the QR code, or the frame to its right. */
export type BarcodeLayout = "vertical" | "horizontal";

/** QR error-correction level chosen by the damage-first degradation ladder. */
export type BarcodeErrorCorrectionLevel = "Q" | "M" | "L";

export interface BarcodeSvgResult {
  /** Complete standalone SVG document. */
  svg: string;
  width: number;
  height: number;
  /** The exact string encoded in the QR code. */
  content: string;
  /**
   * Error-correction level actually used. Normally the configured ceiling
   * (`maxErrorCorrection`, default "M"); drops below it only for unusually
   * long PII so the code still fits the fixed frame.
   */
  errorCorrectionLevel: BarcodeErrorCorrectionLevel;
  /** QR symbol version (1-40), for scanner-fixture attribution. */
  qrVersion: number;
  /** Rendered size of one QR module, in output pixels. */
  modulePx: number;
  /**
   * True when the ladder had to trade scan robustness to fit the payload
   * (error correction below the configured ceiling, or modules below the ideal
   * size). False for essentially all real records. Log this to observe the
   * long tail at scale.
   */
  degraded: boolean;
}

const DEFAULT_NAVY = "#010A4F";
const DEFAULT_QR = "#000000";
const DEFAULT_TEXT = "#FFFFFF";
// White ground under the QR box and the gap above it, so the symbol's light
// modules and its top quiet zone are light on any host document. The QR box
// spans the full badge width, so the badge carries no quiet zone on the left,
// right and bottom: the host document supplies that margin.
const FRAME_BACKGROUND = "#FFFFFF";
export const FRAME_VIEWBOX_WIDTH = 96;
const FRAME_HEADER_HEIGHT = 47;
// White gap between the header and the QR box: the only quiet-zone margin the
// badge itself supplies (the header above it is dark). It is four modules for
// a version 10 symbol, the smallest a full record encodes as, and fewer for
// shorter payloads, whose larger modules have the scan headroom to spare. Odd
// so the viewBox height is even and every supported PNG width has an integer
// pixel height.
export const FRAME_QR_GAP = 7;
export const FRAME_QR_BOX_X = 0;
export const FRAME_QR_BOX_Y = FRAME_HEADER_HEIGHT + FRAME_QR_GAP;
export const FRAME_QR_BOX_SIZE = FRAME_VIEWBOX_WIDTH;
const FRAME_VIEWBOX_HEIGHT = FRAME_QR_BOX_Y + FRAME_QR_BOX_SIZE;
// At this width, a realistic fully-populated PII record renders QR modules at
// or above IDEAL_MODULE_PX at the default "M" ceiling (the pristine tier).
const MIN_BADGE_WIDTH = 480;

// Horizontal layout: the QR box on the left at the full badge height, the same
// white gap as the vertical layout, then the light-tinted brand frame (70x80
// design units, scaled to the QR box's height). The gap is the quiet zone on the
// QR's right, as the vertical gap is below the header, and the tint before the
// frame's text adds to it. The host document supplies the other three sides.
// The panel is one unit wider than the scaled design (85, not 84), with the text
// centred in it, so the viewBox width is even and every supported PNG width is
// an integer. The minimum width renders the QR box at 480 px, matching the
// vertical layout's minimum.
const HORIZONTAL_QR_BOX_SIZE = FRAME_QR_BOX_SIZE;
const HORIZONTAL_FRAME_X = HORIZONTAL_QR_BOX_SIZE + FRAME_QR_GAP;
const HORIZONTAL_FRAME_WIDTH = 85;
const HORIZONTAL_FRAME_SCALE = 1.2;
// Centres the 84-unit scaled design in the 85-unit panel.
const HORIZONTAL_FRAME_TEXT_X = 0.5;
const HORIZONTAL_VIEWBOX_WIDTH = HORIZONTAL_FRAME_X + HORIZONTAL_FRAME_WIDTH;
const HORIZONTAL_MIN_BADGE_WIDTH = 940;

/** Fixed frame geometry for one layout, in viewBox units. */
export interface BadgeGeometry {
  readonly viewboxWidth: number;
  readonly viewboxHeight: number;
  readonly qrBoxX: number;
  readonly qrBoxY: number;
  readonly qrBoxSize: number;
  /** Default and minimum badge width. */
  readonly minWidth: number;
}

export const VERTICAL_GEOMETRY: BadgeGeometry = {
  viewboxWidth: FRAME_VIEWBOX_WIDTH,
  viewboxHeight: FRAME_VIEWBOX_HEIGHT,
  qrBoxX: FRAME_QR_BOX_X,
  qrBoxY: FRAME_QR_BOX_Y,
  qrBoxSize: FRAME_QR_BOX_SIZE,
  minWidth: MIN_BADGE_WIDTH,
};

export const HORIZONTAL_GEOMETRY: BadgeGeometry = {
  viewboxWidth: HORIZONTAL_VIEWBOX_WIDTH,
  viewboxHeight: HORIZONTAL_QR_BOX_SIZE,
  qrBoxX: 0,
  qrBoxY: 0,
  qrBoxSize: HORIZONTAL_QR_BOX_SIZE,
  minWidth: HORIZONTAL_MIN_BADGE_WIDTH,
};

/**
 * The geometry for `layout`. Guards the value at runtime: `layout` is a public
 * option, so an untyped (JS) caller could pass anything.
 */
export function badgeGeometry(layout: BarcodeLayout = "vertical"): BadgeGeometry {
  if (layout === "vertical") return VERTICAL_GEOMETRY;
  if (layout === "horizontal") return HORIZONTAL_GEOMETRY;
  throw new Error(`layout must be "vertical" or "horizontal" (received ${JSON.stringify(layout)})`);
}

export const FINDER_SIZE = 7;
// Degradation ladder, highest-ECC-first (Q -> M -> L; Q is the densest, most
// damage-tolerant level). The branded frame's outer size is fixed, so the only
// levers are error-correction level and module size inside the fixed QR box.
// Starting from the caller's ceiling (`maxErrorCorrection`, default "M"), we
// keep the highest correction level (best damage recovery: Q ~25%, M ~15%,
// L ~7%) whose modules still clear the floor, stepping down only when forced,
// and never varying the frame. A higher ceiling means more modules (a denser
// code) for the same payload; "M" is the visually cleaner default, "Q" trades
// density for damage tolerance. Error correction is invisible to the scan
// service, which only reads the decoded URL.
const FULL_ERROR_CORRECTION_LADDER = ["Q", "M", "L"] as const;
export const DEFAULT_MAX_ERROR_CORRECTION = "M" as const;

/**
 * The ladder from `ceiling` down to "L", e.g. "M" yields ["M", "L"].
 *
 * Guards the ceiling at runtime: `maxErrorCorrection` is a public option, so an
 * untyped (JS) caller could pass an unexpected value. Without this, `indexOf`
 * would return -1 and `slice(-1)` would silently force ["L"], the weakest
 * level. Fail loudly instead.
 */
export function errorCorrectionLadder(ceiling: "Q" | "M"): readonly BarcodeErrorCorrectionLevel[] {
  // Validate against the allowed ceilings, not just membership in the full
  // ladder: "L" is a real ladder entry but not a valid ceiling, and would
  // otherwise pass through as an L-only (weakest) ladder.
  if (ceiling !== "Q" && ceiling !== "M") {
    throw new Error(`maxErrorCorrection must be "Q" or "M" (received ${JSON.stringify(ceiling)})`);
  }
  return FULL_ERROR_CORRECTION_LADDER.slice(FULL_ERROR_CORRECTION_LADDER.indexOf(ceiling));
}

// Pristine target: at or above this module size (px) at the chosen ceiling, the
// code is not considered degraded.
export const IDEAL_MODULE_PX = 4;
// Absolute floor: a module smaller than this (px) is unreliable for real-world
// scans, so we hard-error rather than emit it. Evaluated at the badge's width.
const MIN_MODULE_PX = 3;

function renderModules(
  matrixData: Uint8Array,
  size: number,
  moduleSize: number,
  color: string,
): string {
  const parts: string[] = [];

  for (let row = 0; row < size; row++) {
    for (let col = 0; col < size; col++) {
      if (isFinderModule(row, col, size)) continue;
      if (!matrixData[row * size + col]) continue;
      const x = col * moduleSize;
      const y = row * moduleSize;
      parts.push(
        `<rect x="${round2(x)}" y="${round2(y)}" width="${round2(moduleSize)}" ` +
          `height="${round2(moduleSize)}" fill="${color}"/>`,
      );
    }
  }

  return parts.join("");
}

export function isFinderModule(row: number, col: number, size: number): boolean {
  const inTop = row < FINDER_SIZE;
  const inLeft = col < FINDER_SIZE;
  const inRight = col >= size - FINDER_SIZE;
  const inBottom = row >= size - FINDER_SIZE;
  return (inTop && inLeft) || (inTop && inRight) || (inBottom && inLeft);
}

function renderFinders(size: number, moduleSize: number, color: string): string {
  const lastFinderOrigin = (size - FINDER_SIZE) * moduleSize;
  return (
    renderFinder(0, 0, moduleSize, color) +
    renderFinder(lastFinderOrigin, 0, moduleSize, color) +
    renderFinder(0, lastFinderOrigin, moduleSize, color)
  );
}

function renderFinder(originX: number, originY: number, moduleSize: number, color: string): string {
  const outer = FINDER_SIZE * moduleSize;
  const innerOffset = moduleSize;
  const inner = outer - moduleSize * 2;
  const dotOffset = moduleSize * 2;
  const dot = moduleSize * 3;
  const ringPath = `${roundedRectPath(originX, originY, outer, outer, moduleSize * 1.4)} ${roundedRectPath(
    originX + innerOffset,
    originY + innerOffset,
    inner,
    inner,
    moduleSize,
  )}`;

  return (
    `<path d="${ringPath}" fill="${color}" fill-rule="evenodd"/>` +
    `<rect x="${round2(originX + dotOffset)}" y="${round2(originY + dotOffset)}" ` +
    `width="${round2(dot)}" height="${round2(dot)}" rx="${round2(moduleSize * 0.65)}" ` +
    `fill="${color}"/>`
  );
}

function roundedRectPath(
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number,
): string {
  const left = round2(x);
  const top = round2(y);
  const right = round2(x + width);
  const bottom = round2(y + height);
  const r = round2(Math.min(radius, width / 2, height / 2));

  return (
    `M${round2(x + radius)} ${top}H${round2(x + width - radius)}` +
    `A${r} ${r} 0 0 1 ${right} ${round2(y + radius)}` +
    `V${round2(y + height - radius)}A${r} ${r} 0 0 1 ${round2(x + width - radius)} ${bottom}` +
    `H${round2(x + radius)}A${r} ${r} 0 0 1 ${left} ${round2(y + height - radius)}` +
    `V${round2(y + radius)}A${r} ${r} 0 0 1 ${round2(x + radius)} ${top}Z`
  );
}

export function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

