/**
 * Render the branded Verifiabl barcode as SVG.
 *
 * Takes the Verifiabl reference from `client.registerNonPii` and the encrypted PII
 * ciphertext from `encryptPii`, then returns a standalone SVG suitable for
 * embedding in a payslip PDF.
 *
 * The QR spans the full badge width (vertical layout) or height (horizontal
 * layout) on a white ground. Place the badge with a clear light margin of at
 * least four QR modules (`modulePx` in the result; a tenth of the QR's side
 * covers any realistic record) on every side the badge leaves open: the left,
 * right and bottom for the vertical layout, and the left, top and bottom for the
 * horizontal layout. That margin is the QR quiet zone, which the badge does not
 * carry itself on those sides.
 *
 * Throws {@link QrCapacityError} when the encrypted PII is too long to encode.
 */
export function createBarcodeSvg(
  parts: BarcodeParts,
  options: BarcodeSvgOptions = {},
): BarcodeSvgResult {
  rejectRemovedBarcodeFormat(options);
  const geometry = badgeGeometry(options.layout);
  const { width = geometry.minWidth } = options;
  const badgeWidth = validateBadgeWidth(width, "width", geometry.minWidth);

  const scanOptions: ScanUrlOptions = {};
  if (options.environment !== undefined) {
    scanOptions.environment = options.environment;
  }
  if (options.scanBaseUrl !== undefined) {
    scanOptions.scanBaseUrl = options.scanBaseUrl;
  }
  const encoding = buildQrEncoding(parts, scanOptions);
  const content = encoding.content;

  const ladder = errorCorrectionLadder(options.maxErrorCorrection ?? DEFAULT_MAX_ERROR_CORRECTION);
  const { qr, errorCorrectionLevel, size, moduleSize, modulePx } = selectQrRendering(
    encoding.data,
    badgeWidth,
    ladder,
    content.length,
    geometry,
  );
  const matrixData = qr.modules.data;
  const degraded = errorCorrectionLevel !== ladder[0] || modulePx < IDEAL_MODULE_PX;

  const height = round2((badgeWidth * geometry.viewboxHeight) / geometry.viewboxWidth);

  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${round2(badgeWidth)}" height="${round2(height)}" ` +
    `viewBox="0 0 ${geometry.viewboxWidth} ${geometry.viewboxHeight}" role="img" ` +
    `aria-label="Secured by Verifiabl verification barcode">` +
    (geometry === HORIZONTAL_GEOMETRY ? renderHorizontalFrame() : renderVerticalFrame()) +
    `<g transform="translate(${geometry.qrBoxX} ${geometry.qrBoxY})">` +
    `<g shape-rendering="crispEdges">` +
    renderModules(matrixData, size, moduleSize, DEFAULT_QR) +
    `</g>` +
    renderFinders(size, moduleSize, DEFAULT_QR) +
    `</g></svg>`;

  return {
    svg,
    width: badgeWidth,
    height: round2(height),
    content,
    errorCorrectionLevel,
    qrVersion: (size - 17) / 4,
    modulePx: round2(modulePx),
    degraded,
  };
}

export interface SelectedQrRendering {
  qr: ReturnType<typeof QRCode.create>;
  errorCorrectionLevel: BarcodeErrorCorrectionLevel;
  size: number;
  moduleSize: number;
  modulePx: number;
}

/**
 * Which capacity limit the QR content exceeded.
 *
 * - `qr-capacity`: the content is longer than any QR version holds, at any
 *   error-correction level. A wider badge does not help.
 * - `frame-fit`: the content encodes, but only into a symbol whose modules fall
 *   below the scannable floor inside the fixed frame at this width. A wider
 *   badge can carry it.
 */
export type QrCapacityFailureReason = "qr-capacity" | "frame-fit";

/** What the renderer was asked for when it ran out of capacity. */
export interface QrCapacityErrorDetail {
  reason: QrCapacityFailureReason;
  /** Length of the QR content (the scan URL) in characters. */
  contentLength: number;
  /** Badge width attempted, in SVG user units (SVG) or pixels (PNG). */
  badgeWidth: number;
}

/**
 * Thrown by {@link createBarcodeSvg} and `createBarcodePng` when the QR content
 * does not fit. The PII behind it is caller-supplied, so this is rejected input
 * rather than a renderer fault: catch it to report the length back to the
 * caller instead of failing the surrounding operation.
 */
export class QrCapacityError extends Error {
  readonly reason: QrCapacityFailureReason;
  readonly contentLength: number;
  readonly badgeWidth: number;

  constructor(detail: QrCapacityErrorDetail) {
    super(describeQrCapacityFailure(detail));
    this.name = "QrCapacityError";
    this.reason = detail.reason;
    this.contentLength = detail.contentLength;
    this.badgeWidth = detail.badgeWidth;
    Object.setPrototypeOf(this, QrCapacityError.prototype);
  }
}

function describeQrCapacityFailure(detail: QrCapacityErrorDetail): string {
  if (detail.reason === "qr-capacity") {
    return (
      `The QR content (scan URL) is too large to encode in a QR code at any error-correction ` +
      `level (${detail.contentLength} characters). Shorten the PII fields and try again.`
    );
  }
  return (
    `The PII is too long to render a scannable barcode in the branded frame at width ` +
    `${detail.badgeWidth}, even at the lowest error correction. Shorten the PII fields and try ` +
    `again.`
  );
}

/**
 * Walk the degradation ladder and pick the rendering that fits the fixed
 * frame: the highest error-correction level (starting from the caller's
 * ceiling) whose modules still clear MIN_MODULE_PX at this width. The frame's
 * outer width and height never change. Throws {@link QrCapacityError} if even
 * the lowest level cannot fit, so an over-long payload fails loudly at issuance
 * instead of producing an unscannable code.
 */
export interface QrEncoding {
  readonly content: string;
  readonly data: string | QRCodeSegment[];
}

/** Build explicit byte/alphanumeric segments for the current V2 format. */
export function buildQrEncoding(parts: BarcodeParts, options: ScanUrlOptions): QrEncoding {
  const built = buildScanUrlParts(parts, options);
  return {
    content: built.content,
    data: [
      { data: Buffer.from(built.bytePrefix, "utf8"), mode: "byte" },
      { data: built.alphanumericCiphertext, mode: "alphanumeric" },
    ],
  };
}

export function selectQrRendering(
  data: string | QRCodeSegment[],
  badgeWidth: number,
  ladder: readonly BarcodeErrorCorrectionLevel[],
  contentLength?: number,
  geometry: BadgeGeometry = VERTICAL_GEOMETRY,
): SelectedQrRendering {
  const scale = badgeWidth / geometry.viewboxWidth;
  let densestSize: number | null = null;
  for (const errorCorrectionLevel of ladder) {
    let qr: ReturnType<typeof QRCode.create>;
    try {
      qr = createQr(data, errorCorrectionLevel);
    } catch (error) {
      // The qrcode library throws "...too big to be stored..." when the content
      // exceeds capacity at this level; a lower level holds more, so try it.
      // Surface any other (unexpected) failure instead of masking it.
      if (error instanceof Error && error.message.includes("too big")) {
        continue;
      }
      throw error;
    }
    const size = qr.modules.size;
    const moduleSize = geometry.qrBoxSize / size;
    const modulePx = moduleSize * scale;
    if (modulePx >= MIN_MODULE_PX) {
      return { qr, errorCorrectionLevel, size, moduleSize, modulePx };
    }
    densestSize = size;
  }
  const reason: QrCapacityFailureReason = densestSize === null ? "qr-capacity" : "frame-fit";
  const measuredLength = contentLength ?? (typeof data === "string" ? data.length : 0);
  throw new QrCapacityError({ reason, contentLength: measuredLength, badgeWidth });
}

function createQr(
  data: string | QRCodeSegment[],
  errorCorrectionLevel: BarcodeErrorCorrectionLevel,
): ReturnType<typeof QRCode.create> {
  if (typeof data === "string") return QRCode.create(data, { errorCorrectionLevel });

  // qrcode@1.x uses an asymmetric N4 calculation and a different tie order
  // from ISO/IEC 18004:2024. Select the mask with the standard score used by
  // the .NET encoder so both SDKs produce the same mixed-mode matrix.
  const maskOrder = [2, 3, 7, 4, 6, 5, 0, 1] as const;
  let best: ReturnType<typeof QRCode.create> | undefined;
  let lowestPenalty = Number.POSITIVE_INFINITY;
  for (const maskPattern of maskOrder) {
    const candidate = QRCode.create(data, { errorCorrectionLevel, maskPattern });
    const penalty = qrPenalty(candidate.modules.data, candidate.modules.size);
    if (penalty < lowestPenalty) {
      best = candidate;
      lowestPenalty = penalty;
    }
  }
  if (best === undefined) throw new Error("QR mask selection failed");
  return best;
}

function qrPenalty(modules: Uint8Array, size: number): number {
  const at = (row: number, col: number): number =>
    row < 0 || col < 0 || row >= size || col >= size ? 0 : (modules[row * size + col] ?? 0);
  let sameColor = 0;
  for (let outer = 0; outer < size; outer++) {
    for (const vertical of [false, true]) {
      let previous = -1;
      let run = 0;
      for (let inner = 0; inner < size; inner++) {
        const value = vertical ? at(inner, outer) : at(outer, inner);
        if (value === previous) {
          run++;
        } else {
          if (run >= 5) sameColor += 3 + run - 5;
          previous = value;
          run = 1;
        }
      }
      if (run >= 5) sameColor += 3 + run - 5;
    }
  }

  let blocks = 0;
  for (let row = 0; row < size - 1; row++) {
    for (let col = 0; col < size - 1; col++) {
      const value = at(row, col);
      if (
        at(row, col + 1) === value &&
        at(row + 1, col) === value &&
        at(row + 1, col + 1) === value
      ) {
        blocks += 3;
      }
    }
  }

  let finderPatterns = 0;
  const isFinder = (read: (offset: number) => number, start: number): boolean =>
    read(start) === 1 &&
    read(start + 1) === 0 &&
    read(start + 2) === 1 &&
    read(start + 3) === 1 &&
    read(start + 4) === 1 &&
    read(start + 5) === 0 &&
    read(start + 6) === 1;
  const allLight = (read: (offset: number) => number, start: number, length: number): boolean => {
    for (let offset = 0; offset < length; offset++) {
      if (read(start + offset) !== 0) return false;
    }
    return true;
  };
  for (let outer = 0; outer < size; outer++) {
    for (const vertical of [false, true]) {
      const read = (offset: number): number => (vertical ? at(offset, outer) : at(outer, offset));
      for (let start = 0; start <= size - 7; start++) {
        if (!isFinder(read, start)) continue;
        const left4Right1 = allLight(read, start - 4, 4) && read(start + 7) === 0;
        const left1Right4 = read(start - 1) === 0 && allLight(read, start + 7, 4);
        if (left4Right1 || left1Right4) finderPatterns += 40;
      }
    }
  }

  let dark = 0;
  for (const module of modules) dark += module;
  const total = size * size;
  const balance = 10 * Math.floor(Math.abs(dark - Math.floor(total / 2)) / Math.floor(total / 20));
  return sameColor + blocks + finderPatterns + balance;
}

function validateBadgeWidth(value: number, name: string, minWidth: number): number {
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error(`${name} must be a positive number`);
  }
  if (value < minWidth) {
    throw new Error(`${name} must be at least ${minWidth}`);
  }
  return value;
}
